// https://www.shadertoy.com/view/4llXD7

// half_size.x = width
// half_size.y = height
// radius.x = top-right  
// radius.y = bottom-right
// radius.z = top-left
// radius.w = bottom-left
float rectSDF(in vec2 center_position, in vec2 half_size, in vec4 radius) {
    radius.xy = (center_position.x > 0.0) ? radius.xy : radius.zw;
    radius.x  = (center_position.y > 0.0) ? radius.x  : radius.y;
    vec2 q = abs(center_position) - half_size + radius.x;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - radius.x;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    const vec4 borderColor = vec4(1.0, 0.0, 0.0, 1.0);
    const vec4 backgroundColor = vec4(1.0);
    const vec4 radius = vec4(0.0, 200.0, 10.0, 60.0);
	vec2 halfSize = vec2(400.0, 200.0);
	vec2 position = fragCoord - iResolution.xy / 2.0;

	float dist = rectSDF(position, halfSize, radius);
    fragColor = mix(borderColor, backgroundColor, smoothstep(0.0, 1.0, dist));
}
